using System;
using System.IO;
using System.Net;
using System.Text;
using System.Drawing;
using System.Windows.Forms;
using System.Diagnostics;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Threading.Tasks;

class Center : Form {
 readonly JavaScriptSerializer json=new JavaScriptSerializer(){MaxJsonLength=12000000};
 readonly string home=AppDomain.CurrentDomain.BaseDirectory;
 string endpoint, token, ready; Process backend; bool closing, polling, framing;
 Label connection=new Label(), telemetry=new Label(); TextBox report=new TextBox(), log=new TextBox(), goal=new TextBox();
 ComboBox runs=new ComboBox(); PictureBox scene=new PictureBox(), camera=new PictureBox(); NumericUpDown seed=new NumericUpDown();
 ProgressBar progress=new ProgressBar(); List<object> snapshots=new List<object>(); FlowLayoutPanel commands=new FlowLayoutPanel();
 public Center(){
 Text="Drone Command Center"; Width=1280;Height=900;MinimumSize=new Size(1000,700); BackColor=Color.FromArgb(12,18,27);ForeColor=Color.White; Font=new Font("Segoe UI",10); StartPosition=FormStartPosition.CenterScreen;
 string icon=Path.Combine(home,"drone-command-center.ico");if(File.Exists(icon))Icon=new Icon(icon);
 var root=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(16)};
 root.RowStyles.Add(new RowStyle(SizeType.Absolute,65));root.RowStyles.Add(new RowStyle(SizeType.Absolute,115));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,95));Controls.Add(root);
 connection.Text="DRONE COMMAND CENTER  |  Starting private engine…";connection.Dock=DockStyle.Fill;connection.Font=new Font("Segoe UI",18,FontStyle.Bold);root.Controls.Add(connection,0,0);
 commands.Dock=DockStyle.Fill;root.Controls.Add(commands,0,1);
 Button(commands,"Obstacle simulation",async()=>await Launch("preview"));Button(commands,"Play selected policy",async()=>await Launch("policy"));Button(commands,"Train V006 repeat",async()=>await Launch("train"));
 Button(commands,"Lab folder",()=>{Process.Start("explorer.exe","D:\\drone-rl-lab");return Task.FromResult(0);});
 Button(commands,"AI guide",()=>{var f=new Form(){Text="AI training guide",Width=1000,Height=760};var b=new WebBrowser(){Dock=DockStyle.Fill};f.Controls.Add(b);b.Navigate("D:\\drone-rl-lab\\tether_sim\\guide.html");f.Show(this);return Task.FromResult(0);});
 Button(commands,"Replay",async()=>await Command(new{type="reset",scenario="lift_carry"}));Button(commands,"Pause / resume",async()=>await Command(new{type="pause"}));Button(commands,"Wind pulse",async()=>await Command(new{type="gust"}));
 foreach(string view in new[]{"overview","follow","inspect","onboard"}){string v=view;Button(commands,v,async()=>await Command(new{type="view",mode=v}));}
 foreach(string controller in new[]{"PD","best","final"}){string v=controller;Button(commands,v,async()=>await Command(new{type="controller",controller=v}));}
 seed.Minimum=0;seed.Maximum=int.MaxValue;seed.Value=21001;seed.Width=95;commands.Controls.Add(seed);Button(commands,"Apply layout",async()=>await Command(new{type="seed",seed=(int)seed.Value}));
 goal.Text="go to 1.2 -0.5";goal.Width=155;commands.Controls.Add(goal);Button(commands,"Go",async()=>await Command(new{type="goal",prompt=goal.Text}));
 var body=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=2,RowCount=1};body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,68));body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,32));root.Controls.Add(body,0,2);
 var flight=new TableLayoutPanel(){Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};flight.RowStyles.Add(new RowStyle(SizeType.Percent,100));flight.RowStyles.Add(new RowStyle(SizeType.Absolute,85));body.Controls.Add(flight,0,0);
 scene.Dock=DockStyle.Fill;scene.SizeMode=PictureBoxSizeMode.Zoom;scene.BackColor=Color.FromArgb(7,16,25);flight.Controls.Add(scene,0,0);telemetry.Dock=DockStyle.Fill;telemetry.Text="Launch a simulation to view live physics and send destination commands.";flight.Controls.Add(telemetry,0,1);
 var monitor=new TableLayoutPanel(){Dock=DockStyle.Fill,RowCount=4,ColumnCount=1,Padding=new Padding(12,0,0,0)};monitor.RowStyles.Add(new RowStyle(SizeType.Absolute,35));monitor.RowStyles.Add(new RowStyle(SizeType.Absolute,18));monitor.RowStyles.Add(new RowStyle(SizeType.Percent,65));monitor.RowStyles.Add(new RowStyle(SizeType.Percent,35));body.Controls.Add(monitor,1,0);
 runs.DropDownStyle=ComboBoxStyle.DropDownList;runs.Dock=DockStyle.Fill;runs.SelectedIndexChanged+=(s,e)=>RenderRun();monitor.Controls.Add(runs,0,0);progress.Dock=DockStyle.Fill;monitor.Controls.Add(progress,0,1);
 report.Multiline=true;report.ReadOnly=true;report.ScrollBars=ScrollBars.Vertical;report.Dock=DockStyle.Fill;report.BackColor=Color.FromArgb(20,32,45);report.ForeColor=Color.White;monitor.Controls.Add(report,0,2);camera.Dock=DockStyle.Fill;camera.SizeMode=PictureBoxSizeMode.Zoom;monitor.Controls.Add(camera,0,3);
 log.Multiline=true;log.ReadOnly=true;log.Dock=DockStyle.Fill;log.BackColor=BackColor;log.ForeColor=Color.FromArgb(145,237,206);root.Controls.Add(log,0,3);Log("Simulation only. Physics/training use your existing WSL environments. Training continues when this app closes.");
 Shown+=async(s,e)=>await Boot();FormClosing+=(s,e)=>{closing=true;if(backend!=null&&!backend.HasExited){try{var req=(HttpWebRequest)WebRequest.Create(endpoint+"/api/shutdown");req.Method="POST";req.ContentType="application/json";req.Timeout=2500;byte[] b=Encoding.UTF8.GetBytes(json.Serialize(new{token=token}));req.ContentLength=b.Length;using(var stream=req.GetRequestStream())stream.Write(b,0,b.Length);using(var response=req.GetResponse()){} }catch{backend.Kill();}}if(ready!=null&&File.Exists(ready))File.Delete(ready);};
 }
 void Button(Control parent,string title,Func<Task> action){var b=new Button(){Text=title,AutoSize=true,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(36,55,74),ForeColor=Color.White,Margin=new Padding(3)};parent.Controls.Add(b);b.Click+=async(s,e)=>{b.Enabled=false;try{await action();}catch(Exception ex){Log(ex.Message);}finally{b.Enabled=true;}};}
 void Log(string s){log.Text=DateTime.Now.ToString("HH:mm:ss")+"  "+s+Environment.NewLine+log.Text;}
 Dictionary<string,object> Obj(object v){return v as Dictionary<string,object>??new Dictionary<string,object>();}
 object Get(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)?v:null;}
 double Num(Dictionary<string,object>d,string k){try{return Convert.ToDouble(Get(d,k));}catch{return 0;}}
 string Str(Dictionary<string,object>d,string k){return Convert.ToString(Get(d,k));}
 object[] Arr(object v){return v as object[]??new object[0];}
 async Task<byte[]> Request(string path,object body=null){if(endpoint==null)throw new Exception("Engine is not ready.");return await Task.Run(()=>{var req=(HttpWebRequest)WebRequest.Create(endpoint+path);req.Timeout=20000;req.ReadWriteTimeout=20000;req.Proxy=null;if(body!=null){req.Method="POST";req.ContentType="application/json";byte[] b=Encoding.UTF8.GetBytes(json.Serialize(body));req.ContentLength=b.Length;using(var stream=req.GetRequestStream())stream.Write(b,0,b.Length);}try{using(var response=req.GetResponse())using(var stream=response.GetResponseStream())using(var data=new MemoryStream()){stream.CopyTo(data);return data.ToArray();}}catch(WebException ex){if(ex.Response!=null)using(var reader=new StreamReader(ex.Response.GetResponseStream()))throw new Exception(reader.ReadToEnd());throw;}});}
 async Task<Dictionary<string,object>> Data(string path,object body=null){return Obj(json.DeserializeObject(Encoding.UTF8.GetString(await Request(path,body))));}
 async Task Boot(){try{ready=Path.Combine(Path.GetTempPath(),"drone-center-"+Guid.NewGuid().ToString("N")+".json");var info=new ProcessStartInfo("C:\\Users\\n33du\\AppData\\Local\\Programs\\Python\\Python312\\python.exe","\""+Path.Combine(home,"source","backend.py")+"\" --ready \""+ready+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory="D:\\drone-rl-lab",RedirectStandardError=true};backend=Process.Start(info);for(int i=0;i<150&&!File.Exists(ready);i++){if(backend.HasExited)throw new Exception(await backend.StandardError.ReadToEndAsync());await Task.Delay(200);}if(!File.Exists(ready))throw new Exception("WSL did not become ready within 30 seconds.");var d=Obj(json.DeserializeObject(File.ReadAllText(ready)));token=Str(d,"token");endpoint="http://127.0.0.1:"+Str(d,"port");var status=await Data("/api/status");if(Str(status,"token")!=token)throw new Exception("Private engine identity mismatch.");connection.Text="DRONE COMMAND CENTER  |  Native .NET desktop";Log("Connected to private engine "+endpoint);var timer=new Timer(){Interval=4000};timer.Tick+=async(s,e)=>await Poll();timer.Start();var frames=new Timer(){Interval=100};frames.Tick+=async(s,e)=>await Frames();frames.Start();await Poll();}catch(Exception ex){connection.Text="DRONE COMMAND CENTER  |  Engine unavailable";Log(ex.Message);}}
 async Task Launch(string action){Log("Starting "+action+"…");var d=await Data("/api/launch",new{action=action,token=token,run=Convert.ToString(runs.SelectedItem)});Log(Str(d,"message"));await Poll();}
 async Task Command(object body){var d=await Data("/sim/command",body);Log("Simulation command sent.");}
 async Task Poll(){if(polling||closing)return;polling=true;try{var d=await Data("/api/status");if(Str(d,"token")!=token)throw new Exception("Engine identity mismatch.");snapshots=new List<object>(Arr(Get(d,"runs")));string selected=Convert.ToString(runs.SelectedItem);runs.BeginUpdate();runs.Items.Clear();foreach(var r in snapshots)runs.Items.Add(Str(Obj(r),"name"));if(runs.Items.Contains(selected))runs.SelectedItem=selected;else if(runs.Items.Count>0)runs.SelectedIndex=0;runs.EndUpdate();RenderRun();string error=Str(d,"error");connection.Text="DRONE COMMAND CENTER  |  "+(error!=""?"WSL unavailable":"Monitor connected");if(error!="")Log(error);}catch(Exception ex){Log("Monitor: "+ex.Message);}finally{polling=false;}}
 void RenderRun(){foreach(var o in snapshots){var r=Obj(o);if(Str(r,"name")!=Convert.ToString(runs.SelectedItem))continue;var s=Obj(Get(r,"status"));var c=Obj(Get(r,"config"));progress.Value=(int)Math.Max(0,Math.Min(100,100*Num(s,"timesteps")/Math.Max(1,Num(c,"total_timesteps"))));var text=new StringBuilder();text.AppendLine(Str(r,"name")+" — "+Str(r,"effective"));text.AppendLine("Transitions: "+Num(s,"timesteps").ToString("N0")+" / "+Num(c,"total_timesteps").ToString("N0"));text.AppendLine("Speed: "+Num(s,"steps_per_second").ToString("N0")+" /s");text.AppendLine("Elapsed: "+(Num(s,"elapsed_seconds")/60).ToString("N1")+" min");text.AppendLine("Device: "+(Str(s,"device")==""?Str(c,"device"):Str(s,"device")));text.AppendLine("\r\nEVALUATION (payload RMSE)");var ev=Obj(Get(r,"evaluation"));foreach(string key in new[]{"PD","PPO_residual"}){var v=Obj(Get(ev,key));if(v.Count>0)text.AppendLine(key+": "+(100*Num(v,"mean_payload_rmse_m")).ToString("N2")+" cm; crashes "+Str(v,"crashes")+"; successes "+Str(v,"successes"));}text.AppendLine("\r\nSAVED CHECKPOINTS");foreach(var v in Arr(Get(r,"checkpoints")))text.AppendLine(Convert.ToString(v));text.AppendLine("\r\nPolicy uses known geometry/state. Real drone control is not connected.");report.Text=text.ToString();}}
 void SetImage(PictureBox box,byte[] data){using(var stream=new MemoryStream(data))using(var img=Image.FromStream(stream)){var old=box.Image;box.Image=new Bitmap(img);if(old!=null)old.Dispose();}}
 async Task Frames(){if(framing||closing||endpoint==null)return;framing=true;try{var d=await Data("/api/status");if(!Convert.ToBoolean(Get(d,"viewer")))return;SetImage(scene,await Request("/sim/frame.jpg"));SetImage(camera,await Request("/sim/camera.jpg"));var s=await Data("/sim/state");var drone=Arr(Get(s,"drone"));telemetry.Text="Controller: "+Str(s,"controller")+"    Time: "+Num(s,"time").ToString("N2")+"s    Swing: "+Num(s,"swing_deg").ToString("N1")+"°    FPS: "+Num(s,"fps").ToString("N0")+"    Goal distance: "+Num(s,"goal_distance_m").ToString("N2")+"m\r\n"+Str(s,"stop_reason")+"  "+Str(s,"command_message");}catch(Exception ex){telemetry.Text="Simulator starting / unavailable: "+ex.Message;}finally{framing=false;}}
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var f=new Center();if(args.Length>0&&args[0]=="--self-test"){f.Show();Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(f.home,"self-test.png"));}File.WriteAllText(Path.Combine(f.home,"self-test.txt"),"Native WinForms window created; controls and render passed.");f.Close();return;}if(args.Length>0&&args[0]=="--integration-test"){f.Shown+=async(s,e)=>{try{for(int i=0;i<200&&f.endpoint==null;i++)await Task.Delay(200);await f.Launch("preview");bool live=false;for(int i=0;i<100;i++){try{var state=await f.Data("/sim/state");if(f.Get(state,"drone")!=null){live=true;break;}}catch{}await Task.Delay(200);}if(!live)throw new Exception("Simulator did not start");await f.Command(new{type="goal",prompt="go to 1.2 -0.5"});await Task.Delay(500);await f.Frames();await f.Poll();var state2=await f.Data("/sim/state");if(!f.Str(state2,"command_message").Contains("Route planned"))throw new Exception("Destination command did not plan a route");using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(f.home,"integration-test.png"));}File.WriteAllText(Path.Combine(f.home,"integration-test.txt"),"PASS: private engine identity, WSL monitor, simulation launch, live image, telemetry, destination route command, native window render.");}catch(Exception ex){File.WriteAllText(Path.Combine(f.home,"integration-test.txt"),"FAIL: "+ex);}finally{f.Close();}};}Application.Run(f);}
}
